import { mount, signal, delegate } from 'kerfjs';
import { delegateActions } from 'kerfjs/actions';
import { EmptyState } from '@kerfjs/ui/empty-state';
import '@kerfjs/ui/layout.css';
import './command-palette.css';

// Application adapter: the supplied catalog does not export a CommandPalette.
export type Command = { id: string; label: string; group: string; keywords?: string[]; available?: boolean };
export function mountCommandPalette(root: HTMLElement, commands: readonly Command[], app: {
 recent: readonly string[]; saveRecent(ids: string[]): void; run(command: Command): void; close(): void;
}) {
 const query = signal('');
 const recent = signal([...app.recent]);
 const priorFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
 const enabled = () => commands.filter(command => command.available !== false);
 const matches = () => { const needle = query.value.trim().toLocaleLowerCase(); return enabled().filter(command => [command.label, ...(command.keywords ?? [])].some(text => text.toLocaleLowerCase().includes(needle))); };
 const grouped = () => {
  const results = matches();
  const groups = new Map<string, Command[]>();
  const history = !query.value.trim() ? recent.value.flatMap(id => { const item = results.find(command => command.id === id); return item ? [item] : []; }) : [];
  if (history.length) groups.set('Recent commands', history);
  for (const item of results) {
   if (history.some(command => command.id === item.id)) continue;
   const group = groups.get(item.group) ?? []; group.push(item); groups.set(item.group, group);
  }
  return [...groups];
 };
 const close = () => { app.close(); if (priorFocus?.isConnected) priorFocus.focus(); };
 const stopMount = mount(root, () => <section class="command-palette kui-layout" aria-label="Command palette">
  <div class="kui-surface-body kui-section-stack">
   <label for="command-query">Search commands</label>
   <input id="command-query" type="search" autocomplete="off" value={query.value} aria-describedby="command-help" />
   <p id="command-help">Type to filter. Down Arrow moves to results. Use Up and Down to navigate, Enter to run, or Escape to close.</p>
   <p role="status">{matches().length} matching commands</p>
   <div class="command-results kui-scroll-owner kui-section-stack">
    {matches().length === 0 ? <EmptyState title="No matching commands" detail="Try a different search." /> : grouped().map(([group, items], index) => <section aria-labelledby={'command-group-' + index}><h3 id={'command-group-' + index}>{group}</h3><ul>{items.map(command => <li><button type="button" data-action="run-command" data-command-id={command.id}>{command.label}</button></li>)}</ul></section>)}
   </div>
   <footer class="kui-control-cluster" aria-label="Palette actions"><button type="button" data-action="clear-query">Clear search</button><button type="button" data-action="clear-history">Clear recent history</button><button type="button" data-action="close-palette">Close</button></footer>
  </div>
 </section>);
 const stopActions = delegateActions(root, 'click', {
  'run-command': (_e, element) => {
   const command = enabled().find(item => item.id === (element as HTMLElement).dataset.commandId);
   if (!command) return;
   const next = [command.id, ...recent.value.filter(id => id !== command.id)].slice(0, 10);
   recent.value = next; app.saveRecent(next); close(); app.run(command);
  },
  'clear-query': () => { query.value = ''; queueMicrotask(() => root.querySelector<HTMLInputElement>('#command-query')?.focus()); },
  'clear-history': () => { recent.value = []; app.saveRecent([]); },
  'close-palette': close
 });
 const stopInput = delegate<HTMLInputElement>(root, 'input', '#command-query', (_e, input) => { query.value = input.value; });
 const onKey = (event: KeyboardEvent) => {
  if (event.isComposing) return;
  if (event.key === 'Escape') { event.preventDefault(); close(); return; }
  const buttons = Array.from(root.querySelectorAll<HTMLButtonElement>('[data-action="run-command"]'));
  const index = buttons.indexOf(event.target as HTMLButtonElement);
  const inSearch = (event.target as HTMLElement).id === 'command-query';
  if (!buttons.length || (!inSearch && index < 0)) return;
  let next: number | undefined;
  if (event.key === 'ArrowDown') next = inSearch ? 0 : (index + 1) % buttons.length;
  if (event.key === 'ArrowUp') next = inSearch ? buttons.length - 1 : (index - 1 + buttons.length) % buttons.length;
  if (!inSearch && event.key === 'Home') next = 0;
  if (!inSearch && event.key === 'End') next = buttons.length - 1;
  if (next !== undefined) { event.preventDefault(); buttons[next].focus(); buttons[next].scrollIntoView({ block: 'nearest' }); }
 };
 root.addEventListener('keydown', onKey);
 queueMicrotask(() => root.querySelector<HTMLInputElement>('#command-query')?.focus());
 return () => { root.removeEventListener('keydown', onKey); stopInput(); stopActions(); stopMount(); };
}

