.command-palette { min-width: 0; color: var(--kui-color-text); background: var(--kui-color-surface); border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-l); }
.command-results { max-height: 50dvh; min-height: 0; }
.command-palette ul { margin: 0; padding: 0; list-style: none; }
.command-palette h3 { margin: 0; font-size: var(--kui-font-s); }
.command-palette input { box-sizing: border-box; width: 100%; font: inherit; }
.command-palette button { min-height: 2rem; font: inherit; color: var(--kui-color-text); background: var(--kui-color-surface); border: 1px solid var(--kui-color-border); }
.command-results button { width: 100%; text-align: start; white-space: normal; overflow-wrap: anywhere; }
.command-palette :is(button,input):focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
@media (prefers-reduced-motion:reduce) { .command-palette * { scroll-behavior: auto; } }
